    {
        _statusStrip = new StatusStrip();

        // .NET 9: The default ToolStrip renderer changed from System to
        // ManagerRenderMode. Explicitly set to preserve the .NET 8 look.
        _statusStrip.RenderMode = ToolStripRenderMode.System;

        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Shows an editor dropdown, guarding against the null control case.
    /// .NET 9: DropDownControl(null) now throws ArgumentNullException.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

